using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<Notepad>();

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var notepad = sp.GetRequiredService<Notepad>();

    var tools = new List<AITool>
    {
        AIFunctionFactory.Create(WebSearchTool.SearchAsync),
        AIFunctionFactory.Create(notepad.AddNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    };

    return new ChatClientAgent(
        chatClient,
        instructions: """
            You are a research assistant. When given a topic:
            1. Search the web for relevant information using multiple queries.
            2. Take notes on the key findings using the note-taking tool.
            3. After gathering enough information, provide a comprehensive summary
               that synthesizes your notes.
            Always cite sources when available. Be thorough but concise.
            """,
        name: "ResearchAgent",
        description: "An agent that researches topics by searching the web and taking notes.",
        tools: tools);
});

using var host = builder.Build();

var agent = host.Services.GetRequiredService<ChatClientAgent>();
var logger = host.Services.GetRequiredService<ILoggerFactory>()
    .CreateLogger("ResearchAgent");
var notepad = host.Services.GetRequiredService<Notepad>();

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    try
    {
        Console.WriteLine("\n🔍 Researching...\n");

        var session = await agent.CreateSessionAsync(cancellationToken: CancellationToken.None);
        var response = await agent.RunAsync(messages, session, cancellationToken: CancellationToken.None);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══\n");
        Console.ResetColor();
        Console.WriteLine(response.Text);

        if (notepad.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.Yellow;
            Console.WriteLine($"\n📝 {notepad.Count} note(s) were taken during research.");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        logger.LogError(ex, "Research failed for topic: {Topic}", topic);
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

