using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search functionality via the Brave Search API.
/// Falls back to a simulated search if no API key is configured.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient s_httpClient = new();

    [Description("Search the web for information on a given query. Returns a list of results with titles, URLs, and descriptions.")]
    public static async Task<IReadOnlyList<SearchResult>> SearchAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (default: 5)")] int count = 5)
    {
        var apiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");

        if (!string.IsNullOrEmpty(apiKey))
        {
            return await SearchBraveAsync(query, count, apiKey);
        }

        return SimulateSearch(query, count);
    }

    private static async Task<IReadOnlyList<SearchResult>> SearchBraveAsync(
        string query, int count, string apiKey)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={count}");
        request.Headers.Add("Accept", "application/json");
        request.Headers.Add("X-Subscription-Token", apiKey);

        var response = await s_httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var braveResponse = await response.Content.ReadFromJsonAsync(SearchJsonContext.Default.BraveSearchResponse);
        if (braveResponse?.Web?.Results is null)
            return [];

        return braveResponse.Web.Results
            .Take(count)
            .Select(r => new SearchResult(r.Title ?? "", r.Url ?? "", r.Description ?? ""))
            .ToList();
    }

    private static IReadOnlyList<SearchResult> SimulateSearch(string query, int count)
    {
        // Provides plausible placeholder results when no search API is configured.
        var results = new List<SearchResult>
        {
            new($"Overview of {query} - Wikipedia",
                $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                $"A comprehensive overview covering the history, key concepts, and significance of {query}."),
            new($"{query}: Latest Research and Developments",
                $"https://research.example.com/{Uri.EscapeDataString(query)}",
                $"Recent academic and industry developments related to {query}, including emerging trends."),
            new($"Understanding {query} - Expert Analysis",
                $"https://analysis.example.com/{Uri.EscapeDataString(query)}",
                $"In-depth expert analysis of {query} with practical implications and future outlook."),
            new($"{query} in Practice: Real-World Applications",
                $"https://applications.example.com/{Uri.EscapeDataString(query)}",
                $"How {query} is applied in industry, education, and research with case studies."),
            new($"The Future of {query}",
                $"https://future.example.com/{Uri.EscapeDataString(query)}",
                $"Predictions and forecasts about how {query} will evolve over the next decade."),
        };

        return results.Take(count).ToList();
    }
}

public record SearchResult(string Title, string Url, string Description);

// Brave Search API response models
public class BraveSearchResponse
{
    [JsonPropertyName("web")]
    public BraveWebResults? Web { get; set; }
}

public class BraveWebResults
{
    [JsonPropertyName("results")]
    public List<BraveWebResult>? Results { get; set; }
}

public class BraveWebResult
{
    [JsonPropertyName("title")]
    public string? Title { get; set; }

    [JsonPropertyName("url")]
    public string? Url { get; set; }

    [JsonPropertyName("description")]
    public string? Description { get; set; }
}

