+using System.ComponentModel;
+
+namespace ResearchAgent;
+
+/// <summary>
+/// Provides note-taking functionality for the research agent.
+/// Notes are stored in memory for the duration of a single research session.
+/// </summary>
+public sealed class Notepad
+{
+    private readonly List<Note> _notes = [];
+
+    public int Count => _notes.Count;
+
+    [Description("Add a research note with a title and content. Use this to record key findings during research.")]
+    public string AddNote(
+        [Description("A short title for the note")] string title,
+        [Description("The content of the note, including relevant details and source URLs")] string content)
+    {
+        var note = new Note(title, content, DateTime.UtcNow);
+        _notes.Add(note);
+        return $"Note #{_notes.Count} added: \"{title}\"";
+    }
+
+    [Description("Retrieve all notes taken during the current research session.")]
+    public IReadOnlyList<Note> GetNotes()
+    {
+        return _notes.AsReadOnly();
+    }
+
+    public void Clear() => _notes.Clear();
+}
+
+public record Note(string Title, string Content, DateTime Timestamp);
